/**
 * Event Service Client for Expo/React Native
 * Fetches events from local API server (server-side Ticketmaster calls)
 * This avoids exposing API keys in the client
 * 
 * ARCHITECTURE:
 * - PRIMARY: Supabase (normalized, canonicalized events)
 * - DEBUG: Direct API (/debug-direct-events) - for development only
 * 
 * IMPORTANT: All production traffic goes through Supabase only.
 * The direct API endpoint is deprecated and only for debugging.
 */

// Local API server URL - MUST use host LAN IP for physical iPhone
// The server runs on the host machine and Expo Go on iPhone needs the host IP
const API_BASE_URL = 'http://192.168.68.101:8080';

// Feature flag: Enable fallback to direct API (development only!)
// Set to false in production - all traffic should go through Supabase
const USE_DIRECT_API_FALLBACK = false;

const TIMEOUT = 15000;

/**
 * Generic fetch wrapper
 */
async function fetchFromAPI(endpoint = '/supabase-events') {
  try {
    const response = await fetch(`${API_BASE_URL}${endpoint}`, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      console.warn(`[EventService] API error: ${response.status}`);
      return { error: `HTTP ${response.status}` };
    }

    return await response.json();
  } catch (error) {
    console.warn(`[EventService] Network error: ${error.message}`);
    return { error: error.message };
  }
}

/**
 * Fetch events from Supabase (normalized storage)
 * This is the PRIMARY and ONLY source for events in production
 */
export async function fetchFromSupabase() {
  const data = await fetchFromAPI('/supabase-events');

  if (data.error || !data.events) {
    console.error('[EventService] Supabase fetch failed:', data.error);
    return {
      events: [],
      sources: [],
      metadata: {
        data_source: 'supabase',
        fallback_used: false,
        error: data.error || 'No events returned'
      }
    };
  }

  return {
    events: data.events || [],
    sources: data.sources || [],
    count: data.count || 0,
    metadata: {
      data_source: 'supabase',
      fallback_used: false,
      available_sources: data.sources || [],
      total_count: data.count || 0,
      last_ingested_at: data.last_ingested_at || null,
      ingestion_stats: data.ingestion_stats || null
    }
  };
}

